"def _normalize_input_code(custom_input_code: str) -> str:
    """
    Splits top-level comma-separated assignments (e.g., `arr = [1, 3, 5], target = 5`)
    into newline-separated statements while preserving list literals.
    """
    raw = custom_input_code.strip()
    if not raw:
        return ""
    segments: List[str] = []
    cur = ""
    depth = 0
    in_single = False
    in_double = False
    for ch in raw:
        if ch == "'" and not in_double:
            in_single = not in_single
        elif ch == '"' and not in_single:
            in_double = not in_double
        elif not in_single and not in_double:
            if ch in "([{":
                depth += 1
            elif ch in ")]}":
                depth -= 1
            elif ch == "," and depth == 0 and "=" in cur:
                segments.append(cur.strip())
                cur = ""
                continue
        cur += ch
    if cur.strip():
        segments.append(cur.strip())
    return "\n".join(segments)


